create or replace function public.quest_trigger_geofence(p_location_id uuid,p_geofence_event_id uuid,p_event_type text,p_dwell_seconds integer default null,p_metadata jsonb default '{}'::jsonb) returns integer language plpgsql security invoker as $$ declare s record; v public.quest_participation; n integer:=0; begin if auth.uid() is null then return 0; end if; for s in select qs.* from public.quest_steps qs join public.quests q on q.id=qs.quest_id where q.status='active' and (qs.location_id=p_location_id or qs.geofence_id is not null) and qs.step_type in ('arrive','visit','challenge','custom') order by q.id,qs.step_order loop if qs.geofence_id is not null and not exists(select 1 from public.quest_step_events e where e.quest_step_id=s.id and e.user_id=auth.uid() and e.geofence_event_id=p_geofence_event_id) then null; end if; insert into public.quest_participation(quest_id,user_id) values(s.quest_id,auth.uid()) on conflict(quest_id,user_id) do update set updated_at=now() returning * into v; perform public.quest_record_step(v.id,s.id,p_event_type,'geofence',coalesce(p_metadata,'{}'::jsonb),p_location_id,p_geofence_event_id,null,null); n:=n+1; end loop; return n; end $$;
create or replace function public.quest_trigger_qr(p_qr_code_id uuid,p_location_id uuid default null,p_checkin_id uuid default null,p_metadata jsonb default '{}'::jsonb) returns integer language plpgsql security invoker as $$ declare s record; v public.quest_participation; n integer:=0; begin if auth.uid() is null then return 0; end if; for s in select qs.* from public.quest_steps qs join public.quests q on q.id=qs.quest_id where q.status='active' and qs.qr_code_id=p_qr_code_id and qs.step_type in ('scan','rate','review','evidence','checkin','photo','challenge','custom') order by q.id,qs.step_order loop insert into public.quest_participation(quest_id,user_id) values(s.quest_id,auth.uid()) on conflict(quest_id,user_id) do update set updated_at=now() returning * into v; perform public.quest_record_step(v.id,s.id,'scan','qr',coalesce(p_metadata,'{}'::jsonb),p_location_id,null,p_qr_code_id,p_checkin_id); n:=n+1; end loop; return n; end $$;
